test=[[7,7,7,5,7,7,7,7,5,5,7,7,7,7,7,7,7,7,7,5,7,7,7,7,7,7],[7,7,7,7,5,5,7,7,7,7,7,5,5,7,7,7,7,7,7,7,5,7,7,7,7,7],[7,7,7,7,7,7,5,7,7,7,5,7,7,5,7,7,7,5,7,7,7,7,7,7,7,7],[7,7,7,7,7,7,7,7,7,7,7,5,7,7,7,7,7,7,7,7,7,7,5,7,7,7]]
h,w=len(test),len(test[0]); out=[row[:] for row in test]
for r in range(h):
    inds=[c for c,v in enumerate(test[r]) if v==5]
    for c in range(min(inds),max(inds)+1):
        if test[r][c]==7: out[r][c]=3
for c in range(w):
    inds=[r for r in range(h) if test[r][c]==5]
    if len(inds)>=2:
        for r in range(min(inds),max(inds)+1):
            if test[r][c]==7: out[r][c]=3
print(out)
print('\n'.join(' '.join(map(str,row)) for row in out))
